-- Sources d'information du secteur juridique dans le département 17 (Charente-Maritime).
-- 14 sources, 29 contrôles HTTP sur 29 URLs distinctes (sites, pages actualités et flux), toutes en 200 le 2026-11-22.
-- Corpus détaillé : bench/corpus/sources-juridique-17.jsonl
-- Preuve HTTP : bench/results/verification-sources-juridique-17.json
-- Reprise du travail juridique antérieur de la PR #391 (bench/corpus/sources-justice-avocats.jsonl).

-- La table de traçage est déclarée ici en complément pour rester applicable
-- sur une branche qui ne contient pas encore migrate-064-source-verification.sql.
CREATE TABLE IF NOT EXISTS source_verification (
  id                bigserial PRIMARY KEY,
  source_id         text        NOT NULL REFERENCES source(id) ON DELETE CASCADE,
  url               text        NOT NULL,
  code_http         integer,
  content_type      text,
  items             integer     NOT NULL DEFAULT 0 CHECK (items >= 0),
  derniere_item_at  timestamptz,
  ms                integer     NOT NULL CHECK (ms >= 0),
  verifie_at        timestamptz NOT NULL DEFAULT now(),
  user_agent        text        NOT NULL,
  etat              text        NOT NULL CHECK (etat IN ('ok200', 'muette', 'morte', 'lente')),
  motif             text
);

CREATE INDEX IF NOT EXISTS idx_source_verification_source_date
  ON source_verification (source_id, verifie_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS idx_source_verification_verifie_at
  ON source_verification (verifie_at DESC);


